import React, { useState, useEffect } from 'react';
import { XIcon, SearchIcon, PlusIcon, CheckCircleIcon } from './Icons';

interface SkillsSelectionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (skills: string[]) => void;
  initialSkills?: string[];
}

const ALL_SKILLS = [
    'System Design', 'Leadership', 'Project Management', 'Data Analysis', 
    'Agile Methodology', 'Communication', 'Strategic Thinking',
    'Python', 'React', 'Machine Learning', 'Cloud Computing', 'Cybersecurity',
    'UI/UX Design', 'Product Management', 'Financial Modeling', 'Digital Marketing',
    'DevOps', 'Salesforce', 'Negotiation', 'Public Speaking'
];

const SkillsSelectionModal: React.FC<SkillsSelectionModalProps> = ({ isOpen, onClose, onSubmit, initialSkills = [] }) => {
  const [selectedSkills, setSelectedSkills] = useState<string[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (isOpen) {
        setSelectedSkills(initialSkills.length > 0 ? initialSkills : []);
    }
  }, [isOpen, initialSkills]);

  if (!isOpen) return null;

  const toggleSkill = (skill: string) => {
    if (selectedSkills.includes(skill)) {
        setSelectedSkills(selectedSkills.filter(s => s !== skill));
    } else {
        setSelectedSkills([...selectedSkills, skill]);
    }
  };

  const filteredSkills = ALL_SKILLS.filter(s => s.toLowerCase().includes(searchQuery.toLowerCase()));

  const handleSubmit = () => {
      onSubmit(selectedSkills);
      onClose();
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-60 z-[60] flex justify-center items-center p-4" aria-modal="true" role="dialog">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
        <div className="flex justify-between items-center p-6 border-b">
          <div>
            <h2 className="text-2xl font-heading font-bold text-r-gray-900">Personalize your learning</h2>
            <p className="text-sm text-r-gray-500 mt-1">Select skills to get personalized course recommendations.</p>
          </div>
          <button onClick={onClose} className="text-r-gray-400 hover:text-r-gray-600">
            <XIcon className="w-6 h-6" />
          </button>
        </div>

        <div className="p-6 overflow-y-auto flex-grow bg-r-gray-50">
            {/* Search */}
            <div className="relative mb-6">
                <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-r-gray-400" />
                <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Search for skills (e.g. Python, Leadership)..."
                    className="w-full pl-12 pr-4 py-3 border border-r-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-r-blue bg-white"
                />
            </div>

            {/* Skills List */}
            <div>
                <h3 className="text-sm font-bold text-r-gray-700 uppercase tracking-wide mb-3">
                    {searchQuery ? 'Search Results' : 'Available Skills'}
                </h3>
                <div className="flex flex-wrap gap-3">
                    {filteredSkills.map(skill => (
                        <button
                            key={skill}
                            onClick={() => toggleSkill(skill)}
                            className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-colors border ${
                                selectedSkills.includes(skill)
                                    ? 'bg-r-blue text-white border-r-blue'
                                    : 'bg-white text-r-gray-700 border-r-gray-300 hover:border-r-blue hover:text-r-blue'
                            }`}
                        >
                            {selectedSkills.includes(skill) && <CheckCircleIcon className="w-4 h-4" />}
                            {skill}
                            {!selectedSkills.includes(skill) && <PlusIcon className="w-4 h-4" />}
                        </button>
                    ))}
                    {filteredSkills.length === 0 && (
                        <p className="text-r-gray-500 text-sm">No skills found matching "{searchQuery}"</p>
                    )}
                </div>
            </div>
        </div>

        <div className="p-4 border-t bg-white flex justify-between items-center">
            <span className="text-sm text-r-gray-600">{selectedSkills.length} skills selected</span>
            <div className="flex gap-3">
                <button onClick={onClose} className="px-6 py-2 text-sm font-medium text-r-gray-700 bg-white border border-r-gray-300 rounded-lg hover:bg-r-gray-50">Skip</button>
                <button
                    onClick={handleSubmit}
                    className="px-6 py-2 text-sm font-medium text-white bg-r-blue rounded-lg hover:bg-r-blue-dark shadow-md"
                >
                    Save & Continue
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

export default SkillsSelectionModal;

