                  </div>

                  <div className="border-t border-gray-100 mx-4 my-1"></div>

                  {/* Navigation Links */}
                  <div className="py-2">
                    <Link to="/evaluation" className="w-full flex items-center gap-4 px-6 py-3 hover:bg-gray-50 text-gray-700 transition-colors group">
