            <Route path="/certificate/:engagementId" element={<CertificatePage />} />
            <Route path="/session/:sessionId/notes" element={<SessionNotesPage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </HashRouter>
  );
}

