    // In a real app, you'd fetch this based on reportId
    const data = location.state?.reportData || {
        id: reportId,
        state: 'Mumbai',
        empCode: '55077420',
        empName: 'Ajinkya Patil',
        courseId: 'C-2041',
        lessonName: 'Video Assessment (28489)',
        status: 'Pending',
        activityName: 'OJT ACTIVITY TEST (25288)'
