                        {/* Navigation: Next */}
                        <button 
                            onClick={nextImage}
                            className="absolute right-0 lg:-right-20 top-1/2 -translate-y-1/2 p-4 bg-white/10 hover:bg-white/20 rounded-full transition-all text-white group z-20 backdrop-blur-sm"
                            title="Next Photo"
