const MarkAttendancePage: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'attendance' | 'sessions'>('attendance');
  const [sessionCode, setSessionCode] = useState('');
  const [showMarkedSession, setShowMarkedSession] = useState(false);

  const mockSessions = [
    {
      id: 's-example',
      title: 'Example session',
      start: '12-01-2026 01:21:00 PM',
      end: '12-01-2026 01:25:00 PM',
      instructor: 'Ajinkya Patil',
      location: 'Haryana',
      venue: 'Ambala Ua_JC , HR-AMBL-JC-01 , Haryana',
      sessionId: 'N/A',
      seat: 'N/A',
      status: 'Publish'
    },
    {
      id: 's-9901',
      title: 'Digital Marketing Foundations',
      start: '15-01-2026 10:00:00 AM',
      end: '15-01-2026 12:00:00 PM',
      instructor: 'Priya Sharma',
      location: 'Mumbai',
      venue: 'RCP, TC-22, 2nd Floor, Mumbai',
      sessionId: 'ILT-9901',
      seat: 'A-22',
      status: 'Publish'
    }
  ];

  const handleMark = () => {
    if (sessionCode.trim()) {
      setShowMarkedSession(true);
    } else {
      alert("Please enter a session code.");
    }
  };

  const handleJoinMeeting = () => {
    window.open('https://jiomeetpro.jio.com/', '_blank');
  };

  const handleStartAssessment = (sessionId: string) => {
    navigate(`/assessment/${sessionId}`);
  };

  return (
    <div className="bg-white min-h-screen">
      <div className="max-w-screen-2xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <div className="flex items-center gap-4 mb-8">
          <button 
            onClick={() => navigate(-1)} 
            className="p-2 rounded-full hover:bg-gray-100 transition-colors"
            aria-label="Go back"
          >
            <ArrowLeftIcon className="w-6 h-6 text-r-blue" />
          </button>
          <h1 className="text-2xl font-heading font-bold text-r-gray-900">
            Mark Your Attendance
          </h1>
        </div>

        {/* Tab System */}
        <div className="flex border-b border-gray-200 mb-10 overflow-x-auto">
          <button 
            onClick={() => setActiveTab('attendance')}
            className={`whitespace-nowrap px-8 py-2 text-sm font-bold transition-all border-b-2 ${
                activeTab === 'attendance' 
                ? 'border-r-blue text-r-blue' 
                : 'border-transparent text-r-gray-500 hover:text-r-gray-700'
            }`}
          >
            Attendance
          </button>
          <button 
            onClick={() => setActiveTab('sessions')}
            className={`whitespace-nowrap px-8 py-2 text-sm font-bold transition-all border-b-2 ${
                activeTab === 'sessions' 
                ? 'border-r-blue text-r-blue' 
                : 'border-transparent text-r-gray-500 hover:text-r-gray-700'
            }`}
          >
            Current Sessions
          </button>
        </div>

        {/* Content Section */}
        {activeTab === 'attendance' ? (
          <div className="space-y-6">
            <div className="max-w-3xl">
              <label className="block text-sm font-bold text-r-gray-900 mb-2 uppercase tracking-wide">
                Enter Session Code *
              </label>
              <input 
                type="text" 
                value={sessionCode}
                onChange={(e) => setSessionCode(e.target.value)}
                placeholder="Please enter your session code." 
                className="w-full px-4 py-3 border border-gray-300 rounded-lg text-sm bg-white focus:outline-none focus:ring-2 focus:ring-r-blue/20 transition-all text-r-gray-800"
              />
            </div>

            <button 
              onClick={handleMark}
              className="px-12 py-2.5 bg-nav-blue text-white font-bold rounded-full shadow-md hover:bg-r-blue-dark transition-all transform active:scale-95"
            >
              Mark
            </button>

            {showMarkedSession && (
              <div className="animate-fade-in-up">
                 <h3 className="text-lg font-bold text-green-600 mt-8 mb-2 flex items-center gap-2">
                    <CheckCircleIcon className="w-5 h-5"/> Session Found
                 </h3>
                 <SessionDisplay 
                    session={mockSessions[0]} 
                    onJoin={handleJoinMeeting}
                    onStartAssessment={() => handleStartAssessment(mockSessions[0].id)}
                 />
              </div>
            )}
          </div>
        ) : (
          <div className="animate-fade-in-up">
            <h3 className="text-lg font-bold text-r-gray-800 mb-6 border-l-4 border-nav-blue pl-4">My Current ILT Sessions</h3>
            <div className="space-y-6">
              {mockSessions.map((s, i) => (
                <SessionDisplay 
                    key={i} 
                    session={s} 
                    onJoin={handleJoinMeeting}
                    onStartAssessment={() => handleStartAssessment(s.id)}
                />
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

