                ) : (
                  <div className="text-center py-24 bg-r-gray-50 rounded-[2rem] border-2 border-dashed border-gray-200">
                      <p className="text-gray-500 font-bold uppercase tracking-widest text-xs">No sessions available</p>
                  </div>
                )}
              </div>
            </section>
          )}
        </div>
      </div>
    </div>
  );
};

