             <span className="text-xs font-mono font-bold text-white">{session.sessionId}</span>
          </div>
        </div>

        <div className="p-6 space-y-8">
          {/* 2. ACTIONS SECTION */}
          <div className="flex flex-wrap gap-4 pb-8 border-b border-gray-100">
            {session.actions?.includes('join') && (
              <button 
                onClick={onJoin} 
                className="px-8 py-3 bg-nav-blue text-white font-black rounded-xl text-xs uppercase tracking-widest shadow-lg hover:bg-r-blue-dark transition-all transform active:scale-95"
              >
                Join Meeting
              </button>
            )}
            {session.actions?.includes('assessment') && (
              <button 
                onClick={onStartAssessment} 
                className="px-8 py-3 border-2 border-nav-blue text-nav-blue font-black rounded-xl text-xs uppercase tracking-widest hover:bg-r-blue-50 transition-all transform active:scale-95"
              >
                Start Assessment
              </button>
            )}
            {session.actions?.includes('feedback') && (
              <button 
                onClick={onFeedback} 
                className="px-8 py-3 border-2 border-nav-blue text-nav-blue font-black rounded-xl text-xs uppercase tracking-widest hover:bg-r-blue-50 transition-all transform active:scale-95"
              >
                Submit Feedback
              </button>
            )}
          </div>

          {/* 3. DETAILS SECTION */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-x-8 gap-y-6">
            {/* Timing */}
            <div className="space-y-4">
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                  <CalendarIcon className="w-3.5 h-3.5" /> Start
                </p>
                <p className="text-sm font-bold text-gray-800">{session.start}</p>
              </div>
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                  <ClockIcon className="w-3.5 h-3.5" /> End
                </p>
                <p className="text-sm font-bold text-gray-800">{session.end}</p>
              </div>
            </div>

            {/* People & Identity */}
            <div className="space-y-4">
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                  <UserIcon className="w-3.5 h-3.5" /> Instructor
                </p>
                <p className="text-sm font-bold text-gray-800">{session.instructor}</p>
              </div>
              <div className="sm:hidden">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                  <FileTextIcon className="w-3.5 h-3.5" /> Session ID
                </p>
                <p className="text-sm font-mono font-bold text-gray-800">{session.sessionId}</p>
              </div>
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                  <ArmchairIcon className="w-3.5 h-3.5" /> Seat
                </p>
                <p className="text-sm font-bold text-r-blue">{session.seat}</p>
              </div>
            </div>

            {/* Location & Venue */}
            <div className="md:col-span-2 space-y-4">
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                  <MapPinIcon className="w-3.5 h-3.5" /> Location
                </p>
                <p className="text-sm font-bold text-gray-800">{session.location}</p>
              </div>
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                  <FileTextIcon className="w-3.5 h-3.5" /> Venue
                </p>
                <p className="text-sm text-gray-600 leading-relaxed font-medium">
                  {session.venue}
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const MarkAttendancePage: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'join' | 'sessions'>('join');
  const [sessionCode, setSessionCode] = useState('');
  const [attendedSessionIds, setAttendedSessionIds] = useState<string[]>([]);

  const mockSessions = [
    {
      id: 's-example',
      title: 'Advanced Web Architecture',
      start: '12-01-2026 01:21:00 PM',
      end: '12-01-2026 01:25:00 PM',
      instructor: 'Ajinkya Patil',
      location: 'Haryana',
      venue: 'Ambala Ua_JC , HR-AMBL-JC-01 , Haryana',
      sessionId: 'ILT-5501',
      seat: 'A-12',
      actions: ['join', 'assessment']
    },
    {
      id: 's-9901',
      title: 'Digital Marketing Foundations',
      start: '15-01-2026 10:00:00 AM',
      end: '15-01-2026 12:00:00 PM',
      instructor: 'Priya Sharma',
      location: 'Mumbai',
      venue: 'RCP, TC-22, 2nd Floor, Mumbai',
      sessionId: 'ILT-9901',
      seat: 'A-22',
      actions: ['join', 'assessment']
    },
    {
      id: 's-feedback-only',
      title: 'Leadership & Conflict Resolution',
      start: '20-01-2026 02:00:00 PM',
      end: '20-01-2026 05:00:00 PM',
      instructor: 'Dr. Sameer Khan',
      location: 'Bangalore',
      venue: 'RMZ Eco World, Floor 4, Bangalore',
      sessionId: 'ILT-7722',
      seat: 'B-12',
      actions: ['feedback']
    }
  ];

  const attendedSessionsList = useMemo(() => {
      return mockSessions.filter(s => attendedSessionIds.includes(s.id));
  }, [attendedSessionIds]);

  const handleMark = () => {
    if (sessionCode.trim()) {
      if (!attendedSessionIds.includes('s-example')) {
          setAttendedSessionIds(prev => [...prev, 's-example']);
      }
      setSessionCode('');
    } else {
      alert("Please enter a session code.");
    }
  };

  const handleJoinMeeting = () => {
    window.open('https://jiomeetpro.jio.com/', '_blank');
  };

  const handleStartAssessment = (sessionId: string) => {
    navigate(`/assessment/${sessionId}`);
  };

  const handleSubmitFeedback = () => {
    alert("Redirecting to session feedback form...");
  };

  return (
    <div className="bg-r-gray-50 min-h-screen">
      <div className="max-w-screen-xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex items-center gap-4 mb-10">
          <button 
            onClick={() => navigate(-1)} 
            className="p-2 rounded-full hover:bg-white bg-white shadow-sm border border-gray-200 transition-colors"
            aria-label="Go back"
          >
            <ArrowLeftIcon className="w-6 h-6 text-r-blue" />
          </button>
          <h1 className="text-2xl font-heading font-bold text-r-gray-900">
            Live Sessions
          </h1>
        </div>

        {/* Tab System */}
        <div className="flex border-b border-gray-200 mb-8 sticky top-16 bg-r-gray-50 z-10 overflow-x-auto scrollbar-hide shadow-sm md:shadow-none">
          <button 
            onClick={() => setActiveTab('join')}
            className={`whitespace-nowrap px-8 py-4 text-sm font-black uppercase tracking-widest transition-all border-b-4 ${
                activeTab === 'join' 
                ? 'border-r-blue text-r-blue' 
                : 'border-transparent text-r-gray-400 hover:text-r-gray-600'
            }`}
          >
            Join session
          </button>
          <button 
            onClick={() => setActiveTab('sessions')}
            className={`whitespace-nowrap px-8 py-4 text-sm font-black uppercase tracking-widest transition-all border-b-4 ${
                activeTab === 'sessions' 
                ? 'border-r-blue text-r-blue' 
                : 'border-transparent text-r-gray-400 hover:text-r-gray-600'
            }`}
          >
            My Sessions
          </button>
        </div>

        <div className="animate-fade-in-up">
          {activeTab === 'join' ? (
            <section id="join-session" className="space-y-12">
              <div className="max-w-4xl bg-white p-8 rounded-2xl border border-gray-200 shadow-sm">
                <label className="block text-xs font-black text-r-blue uppercase tracking-[0.2em] mb-4">
                  Mark Session Attendance
                </label>
                <div className="flex flex-col sm:flex-row gap-4">
                  <div className="flex-grow relative">
                      <input 
                          type="text" 
                          value={sessionCode}
                          onChange={(e) => setSessionCode(e.target.value)}
                          placeholder="Enter 6-digit session code" 
                          className="w-full px-6 py-4 border-2 border-gray-100 rounded-xl text-sm bg-r-gray-50 focus:outline-none focus:ring-4 focus:ring-r-blue/10 focus:border-r-blue transition-all text-r-gray-800 font-bold placeholder:font-normal"
                      />
                  </div>
                  <button 
                    onClick={handleMark}
                    className="px-10 py-4 bg-nav-blue text-white font-black uppercase tracking-widest rounded-xl shadow-lg hover:bg-r-blue-dark transition-all transform active:scale-95 text-xs"
                  >
                    Submit Code
                  </button>
                </div>
              </div>

              {attendedSessionsList.length > 0 ? (
                <div className="animate-fade-in">
                   <h3 className="text-xl font-heading font-bold text-r-gray-900 mb-8 border-l-4 border-nav-blue pl-4 uppercase tracking-tight">
                      Session Found for Your Code
                   </h3>
                   <div>
                      {attendedSessionsList.map(session => (
                          <SessionDisplay 
                              key={session.id}
                              session={session} 
                              onJoin={handleJoinMeeting}
                              onStartAssessment={() => handleStartAssessment(session.id)}
                              onFeedback={handleSubmitFeedback}
                          />
                      ))}
                   </div>
                </div>
              ) : (
                <div className="py-24 text-center bg-white rounded-[2rem] border-2 border-dashed border-gray-200 shadow-inner">
                    <div className="w-20 h-20 bg-r-blue/5 rounded-full flex items-center justify-center mx-auto mb-6">
                        <CalendarIcon className="w-10 h-10 text-r-blue/30" />
                    </div>
                    <p className="text-gray-500 font-black uppercase tracking-widest text-xs">No session joined yet</p>
                    <p className="text-gray-400 text-sm mt-2">Enter a code above to see it here.</p>
                </div>
              )}
            </section>
          ) : (
            <section id="my-sessions">
              <div className="mb-8">
                  <h2 className="text-xl font-heading font-bold text-r-gray-900 border-l-4 border-nav-blue pl-4 uppercase tracking-tight">
                    ({mockSessions.length}) All Sessions
                  </h2>
              </div>

              <div>
                {mockSessions.length > 0 ? (
                  mockSessions.map((s) => (
                    <SessionDisplay 
                        key={s.id} 
                        session={s} 
                        onJoin={handleJoinMeeting}
                        onStartAssessment={() => handleStartAssessment(s.id)}
                        onFeedback={handleSubmitFeedback}
                    />
                  ))
                ) : (
                  <div className="text-center py-24 bg-white rounded-[2rem] border-2 border-dashed border-gray-200">
                      <p className="text-gray-500 font-black uppercase tracking-widest text-xs">No sessions available</p>
                  </div>
                )}
              </div>
            </section>
          )}
        </div>
      </div>
    </div>
  );
};

