const getRelatedCourses = (currentPrompt: string, historyMessages: ChatMessage[]): Course[] => {
    const scoreCourse = (course: Course, text: string) => {
        const keywords = text.toLowerCase().split(/\s+/).filter(w => w.length > 3);
        let score = 0;
        const searchTarget = (course.title + ' ' + course.tags.join(' ')).toLowerCase();
        keywords.forEach(kw => {
            if (searchTarget.includes(kw)) score++;
        });
        return score;
    };
    const currentMatches = mockLMSCatalog
        .map(c => ({ course: c, score: scoreCourse(c, currentPrompt) }))
        .sort((a, b) => b.score - a.score)
        .filter(x => x.score > 0)
        .map(x => x.course);
    const historyText = historyMessages.filter(m => m.role === 'user').map(m => m.text).join(' ');
    const historyMatches = mockLMSCatalog
        .map(c => ({ course: c, score: scoreCourse(c, historyText) }))
        .sort((a, b) => b.score - a.score)
        .filter(x => x.score > 0)
        .map(x => x.course);
    const topCurrent = currentMatches.slice(0, 4);
    const topHistory = historyMatches.filter(c => !topCurrent.find(tc => tc.id === c.id)).slice(0, 1);
    let combined = [...topCurrent, ...topHistory];
    if (combined.length < 5) {
        const remaining = mockLMSCatalog.filter(c => !combined.find(ec => ec.id === c.id));
        combined = [...combined, ...remaining.slice(0, 5 - combined.length)];
    }
    return combined;
};

const AIModeView: React.FC<{ initialQuery: string }> = ({ initialQuery }) => {
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [inputValue, setInputValue] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isGuardrailChecking, setIsGuardrailChecking] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const hasInitialized = useRef(false);

    const [attachedFiles, setAttachedFiles] = useState<File[]>([]);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const [customPrompt, setCustomPrompt] = useState('');
    const [preGuardrails, setPreGuardrails] = useState('');
    const [postGuardrails, setPostGuardrails] = useState('');
    const [contextText, setContextText] = useState('');
    const [contextFiles, setContextFiles] = useState<File[]>([]);

    const [isPromptModalOpen, setIsPromptModalOpen] = useState(false);
    const [isContextModalOpen, setIsContextModalOpen] = useState(false);
    const [isGuardrailsModalOpen, setIsGuardrailsModalOpen] = useState(false);

    const [relatedCourses, setRelatedCourses] = useState<Course[]>([]);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages, isLoading, isGuardrailChecking]);

    const handleSendMessage = async (text: string) => {
        if (!text.trim() && attachedFiles.length === 0) return;

        const newUserMsg: ChatMessage = { 
            id: Date.now().toString(), 
            role: 'user', 
            text: text,
            files: attachedFiles.map(f => ({ name: f.name, type: f.type })) 
        };

        const recommended = getRelatedCourses(text, messages);
        setRelatedCourses(recommended);
        setMessages(prev => [...prev, newUserMsg]);

        const currentFiles = [...attachedFiles];
        setInputValue('');
        setAttachedFiles([]);
        setIsLoading(true);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            // Build system instructions with Pre-processing guardrails
            const finalSystemInstruction = [
                customPrompt || "You are a helpful learning assistant for the Reliance New LMS platform.",
                preGuardrails ? `[PRE-PROCESSING GUARDRAILS]: ${preGuardrails}` : ''
            ].filter(Boolean).join('\n\n');

            let promptText = text;
            if (contextText) {
                promptText = `[Context]: ${contextText}\n\n[User Query]: ${text}`;
            }

            const parts: any[] = [{ text: promptText }];
            for (const file of currentFiles) {
                const base64Data = await fileToBase64(file);
                parts.push({ inlineData: { mimeType: file.type, data: base64Data } });
            }
            for (const file of contextFiles) {
                const base64Data = await fileToBase64(file);
                parts.push({ inlineData: { mimeType: file.type, data: base64Data } });
            }

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: { parts },
                config: {
                    tools: [{ googleSearch: {} }],
                    systemInstruction: finalSystemInstruction
                },
            });

            let finalResponseText = response.text || "I couldn't find an answer to that.";

            // Post-processing Guardrails Layer
            if (postGuardrails && response.text) {
                setIsLoading(false);
                setIsGuardrailChecking(true);

                const postResponse = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: `You are a verification layer. Refine or validate the following AI response based on these POST-PROCESSING GUARDRAILS: "${postGuardrails}". 
                    If the response violates guardrails, fix it. If it's safe, you can optionally refine its tone as requested.

                    ORIGINAL RESPONSE:
                    ${response.text}`,
                });

                finalResponseText = postResponse.text || finalResponseText;
                setIsGuardrailChecking(false);
            }

            const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
            const sources: { title: string; url: string }[] = [];
            if (groundingChunks) {
                groundingChunks.forEach((chunk: any) => {
                    if (chunk.web) {
                        sources.push({ title: chunk.web.title || chunk.web.uri, url: chunk.web.uri });
                    }
                });
            }

            const newAiMsg: ChatMessage = { 
                id: (Date.now() + 1).toString(), 
                role: 'model', 
                text: finalResponseText,
                sources: sources.length > 0 ? sources : undefined,
                isGuardrailVerified: !!postGuardrails
            };
            setMessages(prev => [...prev, newAiMsg]);
        } catch (error) {
            console.error("AI Error:", error);
            const errorMsg: ChatMessage = { 
                id: (Date.now() + 1).toString(), 
                role: 'model', 
                text: "Sorry, I encountered an error while processing your request. Please try again." 
            };
            setMessages(prev => [...prev, errorMsg]);
        } finally {
            setIsLoading(false);
            setIsGuardrailChecking(false);
        }
    };

    useEffect(() => {
        if (initialQuery && !hasInitialized.current) {
            hasInitialized.current = true;
            handleSendMessage(initialQuery);
        }
    }, [initialQuery]);

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            setAttachedFiles(prev => [...prev, ...Array.from(e.target.files || [])]);
        }
    };

    return (
        <div className="flex h-full bg-white rounded-xl shadow-sm border border-r-gray-200 overflow-hidden relative">
            <div className="flex-grow flex flex-col h-full relative min-w-0">
                <div className="h-12 flex-shrink-0 border-b bg-white flex items-center justify-between px-4 z-10">
                    <span className="text-sm font-bold text-gray-700">AI Learning Assistant</span>
                    <div className="flex items-center gap-2">
                        <button 
                            onClick={() => setIsPromptModalOpen(true)}
                            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-100 rounded-md transition-colors"
                        >
                            <SettingsIcon className="w-4 h-4 text-gray-500" />
                            Customize Prompt
                        </button>
                        <button 
                            onClick={() => setIsGuardrailsModalOpen(true)}
                            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-100 rounded-md transition-colors"
                        >
                            <ShieldCheckIcon className="w-4 h-4 text-r-blue" />
                            Guardrails
                        </button>
                        <button 
                            onClick={() => setIsContextModalOpen(true)}
                            className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-100 rounded-md transition-colors"
                        >
                            <LayersIcon className="w-4 h-4 text-gray-500" />
                            Context
                        </button>
                    </div>
                </div>

                <div className="flex-grow overflow-y-auto p-6 space-y-6 bg-r-gray-50 scroll-smooth">
                    {messages.length === 0 && !isLoading && (
                        <div className="flex flex-col items-center justify-center h-full text-r-gray-400 opacity-50 text-center px-8">
                            <AppLogoIcon className="w-16 h-16 mb-4 text-indigo-200" />
                            <p className="text-lg font-medium text-gray-600">Ask me anything about your learning journey!</p>
                            <p className="text-sm">Use the tools above to set guardrails and context for my behavior.</p>
                        </div>
                    )}

                    {messages.map((msg) => (
                        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[85%] rounded-2xl p-4 shadow-sm relative ${
                                msg.role === 'user' 
                                    ? 'bg-r-blue text-white rounded-tr-none' 
                                    : 'bg-white text-r-gray-800 border border-r-gray-200 rounded-tl-none'
